        [348191] = "Завдає $s1 криги шкода секунду.",
        [349981] = "Світові ефекти призупинено:\r\n\r\n$?$W1!=0[$@spelldesc348779 $@spellicon22817 $@spellname22817 (${$w1/60}m)][]$?$W2!=0[$@spelldesc348779 $@spellicon22818 $@spellname22818 (${$w2/60}m)][]$?$W3!=0[$@spelldesc348779 $@spellicon22820 $@spellname22820 (${$w3/60}m)][]$?$W4!=0[$@spelldesc348779 $@spellicon22888 $@spellname22888 (${$w4/60}m)][]$?$W5!=0[$@spelldesc348779 $@spellicon16609 $@spellname16609 (${$w5/60}m)][]$?$W6!=0[$@spelldesc348779 $@spellicon24425 $@spellname24425 (${$w6/60}m)][]$?$W7!=0[$@spelldesc348779 $@spellicon15366 $@spellname15366 (${$w7/60}m)][]$?$W8!=0[$@spelldesc348779 $@spellicon23768 $@spellname353694 (${$w8/60}m)][]$?$W10!=0[$@spelldesc348779 $@spellicon430947 $@spellname430947 (${$w10/60}m)][]$?$W11!=0[$@spelldesc348779 $@spellicon438536 $@spellname438536 (${$w11/60}m)][]$?$W12!=0[$@spelldesc348779 $@spellicon446695 $@spellname446695 (${$w12/60}m)][]$?$W13!=0[$@spelldesc348779 $@spellicon460939 $@spellname460939 (${$w13/60}m)][]\r\n\r\n\r\n\r\nПоки світовий ефект призупинено, ви не можете отримувати користь від",
        [350025] = "Швидкість руху зменшено на $s1%.",
        [355363] = "Збільшує критичний імовірність закляття на $s1%, ближнього бою і дальнього бою на $s3% і надає $s2 сила атаки. Триває $d.",
