        [355366] = "Збільшує здоров'я на 300. 15% швидкість до ближнього бою атаки. 10 мана відновлення кожні 5 секунд.",
        [362859] = "|cFFffd200Сезон Майстерності|r\r\n\r\nЗбільшує досвід і золото, отримані за завдання, на $s1%. Завдання підземель і елітні завдання дають додатковий досвід.",
