        [364001] = "|cFFffd200Хардкор|r\r\n$?$W1!=0[$@spelldesc348779$@spellicon364090 $@spellname364090][]$?$W2!=0[$@spelldesc348779$@spellicon364095 $@spellname364095][]$?$W3!=0[$@spelldesc348779$@spellicon364339 $@spellname364339][]$?$W4!=0[$@spelldesc348779$@spellicon364340 $@spellname364340][]$?$W5!=0[$@spelldesc348779$@spellicon364341 $@spellname364341][]\r\n$?$W6!=0[$@spelldesc348779$@spellicon431678 $@spellname431678][]",
