        [427120] = "Союзники в межах $a1 м від Провидця отримують на $s1% більше здоров'я та завдають на $s2% більше шкоди.\r\n\r\nЦі значення збільшуються за кожного живого Майстра Клинка у війську Провидця; кожен надає $427116s1% додаткового здоров'я та $427116s2% додаткової шкоди.",
