        [437132] = "Збільшує Таємної магії і шкода від природи отримано на $s1%.",
        [437146] = "Вшануйте архіваріусів.",
        [437147] = "Вшануйте архіваріусів.",
        [437148] = "Вшануйте архіваріусів.",
        [437324] = "Оглушення.\r\nОтримувану шкоду зменшено на $s3%.\r\nЗцілює отримано зменшено на $s4%.",
        [437327] = "Вас сповнило заряджене натхнення. Витрати мани на всі закляття зменшено, а силу заклять збільшено.",
