        [437353] = "Броню зменшено на $s2%.",
        [437357] = "Закляття сила збільшено і отримує мана поки застосування.",
        [437362] = "Швидкість застосування заклять збільшено.",
        [437377] = "Глибоко зосереджений. Швидкість атаки та опір закляттям збільшено, але швидкість руху зменшено.",
        [437382] = "Невразливий до Мовчанка, Переривання ефекти, і закляття затримка.",
        [437390] = "$s1 Шкода від природи кожні $t1 с.\r\nВлучання імовірність зменшено на $s2%.\r\nРесурс витрати збільшено на $s3%.",
        [437410] = "Отримувану шкоду зменшено на $s1%.",
        [437425] = "$s1 Шкода від природи кожні $t1 с.\r\nВлучання імовірність зменшено на $s2%.\r\nРесурс витрати збільшено на $s3%.",
        [437472] = "$@spellaura437479",
        [437474] = "$@spellaura437479",
        [437475] = "$@spellaura437479",
        [437479] = "Завдає $s1 шкоди від тіні кожні $t1 с до союзники у межах $437480A1 метрів. Цей ефект зарядів.",
        [437480] = "$@spellaura437479",
        [437532] = "Тікає від страху.",
        [437585] = "Завдану шкоду збільшено на $s1%.",
        [437617] = "Швидкість руху зменшено на $s1%.",
        [437621] = "$@spellaura437622",
        [437622] = "Тіні Бальназзара вражають гравців, які не перебувають у межах $437627A1 м від іншого гравця, завдаючи $437648s1 шкоди від тіні.",
        [437627] = "$@spellaura437622",
        [437642] = "$@spellaura437622",
        [437648] = "$@spellaura437622",
        [437650] = "$@spellaura437622",
        [437695] = "Лоа крові вимагає змагання, а не різанини беззахисних! Покиньте рейдову групу, або відчуєте його гнів! Усі характеристики та швидкість руху зменшено на $s1%.",
        [437698] = "Орел! Імовірність критичного удару збільшено!",
        [437699] = "Решка! Швидкість руху збільшено!",
        [437713] = "Збільшує усі шкода завдано на $s1%",
        [437716] = "Ваш наступний атака буде критично удар.",
        [437739] = "Під дією мовчанки.",
        [437751] = "Побитий.",
        [437791] = "$s1% здоров'я відновлено кожні $t1 с.",
        [437799] = "$w $?$w=1[трофей][трофеї] зібрано.",
        [437801] = "Невразливий до мовчанки.",
        [437802] = "Дружні цілі в межах $A1 м стають несприйнятливими до знемовлення.\r\n\r\nВерескливі жахіття впадають у лють, якщо їх уразити.",
        [437809] = "$s2 свята шкода завдано кожні $t2 с.",
        [437813] = "Атака і руху швидкість збільшено на $s1%.",
        [437833] = "$@spellaura437933",
        [437834] = "$@spellaura437933",
        [437840] = "$@spellaura437846",
        [437846] = "Завдає $437840s1 шкоди від вогню ворогам у межах $A1 м кожні $t2 с, а також надає несприйнятливість до Гнітючої темряви.",
        [437847] = "Зцілює отримано зменшено на $s2%.",
        [437868] = "$s1 Шкода від тіні кожні $t1 с.\r\nШкода завдано зменшено на $s2%.",
        [437877] = "Оґом отримує наповнення Світлом.",
        [437881] = "Джаммал’ан отримує наповнення Тінню.",
        [437891] = "свята шкода отримано збільшено на $s2%.",
        [437902] = "$@spellaura",
        [437915] = "Оглушення.",
        [437922] = "Зазнає $437840s1 шкоди від вогню кожні $437846t2 с і несприйнятливий до Гнітючої темряви.",
        [437927] = "Завдає $s1 шкоди від тіні кожні $t1 с.",
        [437928] = "Тікає від страху.",
        [437930] = "Поглинає шкоду.",
        [437933] = "Оглушення.",
        [437984] = "Позначений для підкорення...",
        [437987] = "Підкорений.",
        [438040] = "Очки серії буде перенесено на наступну ціль, уражену здібностями цього розбійника.",
        [438062] = "Воєвода",
        [438089] = "Шкода від природи кожні $t1 с.",
        [438101] = "Шкода завдано зменшено на $s3%.\r\nШвидкість руху зменшено на $s5%.",
        [438136] = "Атака і застосування швидкість зменшено на $s2%.",
        [438142] = "$s1 Шкода від природи кожні $t1 с.\r\nШвидкість руху зменшено на $s2%.",
        [438170] = "Занурює собор у темряву, знемовлюючи всіх гравців.",
        [438288] = "Поблизу причаївся Темний вершник...",
        [438294] = "$s1 шкода від природи завдано до нападникам ближнього бою.",
        [438295] = "Дає змогу відчувати присутність Темних вершників.",
        [438326] = "$s1 шкода від природи завдано до нападникам ближнього бою.",
        [438341] = "$s1 шкода зцілено кожні $t1 с.",
        [438536] = "Збільшує імовірність критичного удару закляття на $s1%, надає $s2 шкода від заклять і зцілення, і збільшує ближнього бою і дальнього бою атака швидкість на $s4%. 120 хвилина тривалість.",
        [438537] = "Збільшує імовірність критичного удару закляття на $s1%, надає $s2 шкода від заклять і зцілення, і збільшує ближнього бою і дальнього бою атака швидкість на $s4%. 120 хвилина тривалість.",
        [438551] = "Більше небезпеки — більше нагород!",
        [438567] = "Побитий.",
        [438710] = "Завдає $w1 вогню шкоди кожні $t1 с.",
        [438715] = "З механічної печі вихлюпується полум’я.",
        [438716] = "$w1 вогню шкоди кожні $t1 с.",
        [438718] = "$w1 вогню шкоди кожні $t1 с.",
        [438719] = "Швидкість руху зменшено на $s2%.",
        [438720] = "Швидкість руху зменшено на $s2%.",
        [438721] = "Оглушення і дуже холод.",
        [438727] = "шкода від природи отримано збільшено на $w1%.",
        [438728] = "$w1 Шкода від природи кожні $t1 с.",
        [438732] = "$w1 Шкода від природи кожні $t1 с.",
        [438735] = "Поки ви наелектризовані, кнопки, схоже, не реагують на дотик.",
        [439155] = "Посилено Інновацією. Закляття завдають до $s1 додаткової шкоди та зцілення, а сила атаки збільшується на $s2.",
        [439471] = "Броню зменшено на $w1.",
        [439472] = "Час між атаками збільшено на $s1%.",
        [439473] = "Силу атаки ближнього бою зменшено на $s1.",
        [439733] = "Невразливий до ефектів поліморфії.\r\nЗменшує мана витрати зцілює протягом час закляття на $439734s1%.\r\nЗбільшує дух на $439734s2% і броня на $439734s3%.\r\nЗбільшує зцілення отримано на $439745s1% для усі члени групи у межах $439745a1 метрів і зцілення завдано на Дикий ріст на $439734s8%.",
        [439745] = "Збільшує зцілення отримано на $s1%.",
        [439748] = "Прикликає зорі з неба.",
        [439753] = "Ви прикликаєте з неба шквал зір по всіх цілях у межах 30 м від заклинача; кожна завдає $50288s1 шкоди від аркани. Також завдає $50294s1 шкоди від аркани всім іншим ворогам у межах $50294a1 м від ворожої цілі. Максимум 20 зір. Триває $48505d.",
        [439756] = "Максимум 20 зір. Триває $48505d.",
        [439958] = "Лоа крові винагороджує ризик.",
        [439959] = "Магічний шкода завдано на закляття і здібності є збільшено на до до $s1.",
        [440014] = "Завдає $w1 вогню шкоди кожні $t1 с.",
        [440072] = "Ви почуваєтеся примарно.",
        [440108] = "Не може атакувати чи застосовувати закляття.",
        [440114] = "Ви можете один раз застосувати Страту незалежно від запасу здоров’я цілі, після чого у вас залишиться $440113s2 люті.",
        [440213] = "Лоа крові вимагає змагання, а не різанини беззахисних! Покиньте рейдову групу, або відчуєте його гнів! Усі характеристики та швидкість руху зменшено на $s1%.",
        [440285] = "Ваш наступний Ланцюгова блискавка, Ланцюгове зцілення, або Виверження лави закляття буде бути миттєвий застосування закляття.",
        [440471] = "$w1 Шкода від природи кожні $t1 с.",
