        [442226] = "Спровокований.",
        [442233] = "Спровокований.",
        [442622] = "Завдає $s1 шкоди від природи кожні $t1 секунд.",
        [442948] = "Невразливий до фізичних атак. Не може атакувати чи використовувати фізичні здібності.",
        [443265] = "Зазнає $s1 вогню шкоди кожні $t1 с.",
        [443278] = "Ваші здібності та закляття можуть вживити насіння у вражених ворожих гуманоїдів, звірів або драконідів.",
        [443302] = "Усі шкода отримано зменшено на $s1%.",
        [443320] = "Фізичний$?$w3>0[, Вогню, Криги, і Природи][] шкода завдано збільшено на $s1% і усі загроза створено зменшено на $s2%.",
        [443369] = "Хрономантична енергія готова до вивільнення. Миттєво зцілює дружню ціль на ${$<healpower>*$436517m1/100}–${$<healpower>*$436517M1/100}.",
        [443464] = "Зцілює $s1 здоров’я кожні $t1 секунд.",
        [443678] = "Після смерті з трупа виросте Цілющий цвіт.",
