        [443975] = "$s1 Шкода від тіні кожні $t1 с.\r\nАтака, застосування, і руху швидкість зменшено на $s2%.",
        [443990] = "Тікає у страх!",
        [444039] = "Ворожі до усі!\r\nМаксимальне здоров'я збільшено на $s1%.",
        [444046] = "Швидкість застосування заклять зменшено на $s1%.",
        [444165] = "Усе отримуване зцілення зменшено на $s1%.\r\nШвидкість руху збільшено на $s2%.\r\n\r\nВаші плоть і кров висмоктано!",
        [444253] = "$444261s1 Шкода від тіні кожні $444255t1 с.\r\nМає імовірність до поширює до поблизу гравці.",
        [444255] = "$@spellaura444253",
        [444261] = "$@spellaura444253",
        [444273] = "$444284s1 Шкода від тіні кожні $t1 с.\r\nМає імовірність до поширює до поблизу гравці.",
        [444280] = "$@spellaura444253",
        [444284] = "$@spellaura444273",
        [444285] = "$444284s1 Шкода від тіні кожні $t1 с.\r\nМає імовірність до поширює до поблизу гравці.",
        [444286] = "$@spellaura444273",
        [444290] = "$@spellaura444273",
        [444291] = "$@spellaura444273",
        [444509] = "Стихії шепочуть до вас, прагнучи допомогти в бою.",
        [444522] = "Тікає для ваш життя.",
        [444678] = "Швидкість застосування заклять зменшено на $s2%.",
        [444681] = "Швидкість застосування заклять зменшено на $s2%.",
        [444892] = "Вас знерухомив смертельний холод! Неможливо рухатися або діяти.",
        [444938] = "Занурений у кошмар.",
        [445080] = "Ворожі до усі!",
        [445081] = "Ви вбили іншого гравця! \r\nШвидкість руху збільшено на $s1%.",
        [445158] = "У пастці Смарагдового Кошмару, зазнає $s6 шкоди кожні $t6 с.",
        [445181] = "Виявити елементальний духи.",
        [445282] = "Обеззброєний!",
        [445284] = "Швидкість атаки і руху швидкість збільшено на $s1%.",
        [445498] = "Тікає у страх!",
        [445522] = "Ваш біс-дослідник зайнятий.",
