        [445801] = "Міцний панцир.",
        [445867] = "Переслідуваний смарагдовими ілюзіями, доки не зустрінете свій страх і не дозволите йому пройти крізь вас.",
        [445868] = "Прокинувся, але якою ціною?",
        [445870] = "Між швидкоплинними снами.",
        [445871] = "Зачарований легкістю сновидців.\r\nСпритність союзників збільшено.",
        [445875] = "Змучений видіннями кошмару.\r\nЗазнає шкідливих ефектів.",
        [445940] = "Оглушення.",
        [446069] = "Ви знайшли друга!",
        [446070] = "Ви знайшли друга!",
        [446088] = "Відновлює $s1 мани кожні $t1 с. Знімається на полях бою та в підземеллях.",
        [446091] = "Ваш розум сповнений невимовного жаху. Отримувану шкоду значно збільшено, а швидкість руху зменшено.",
        [446093] = "Ви є тепер всередині Смарагдовим кошмар",
        [446095] = "Сповнений натхнення.",
        [446097] = "Вдивляється дедалі глибше в Кошмар.",
        [446098] = "Ти все одно мене любитимеш...?",
