        [1218038] = "Скутий льодом, доки кайдани не буде знищено.",
        [1218071] = "Збільшує імовірність для ближнього бою, дальнього бою, або закляття критичний на $s1% і усі характеристики на $s2.",
        [1218072] = "Збільшує сила атаки на $s1, Витривалість на $s3%, і закляття імовірність критичного удару на $s4%.",
        [1218073] = "Збільшує шкода на $s1%.",
        [1218074] = "Збільшує здоров'я на $s1. $s2% швидкість до ближнього бою атаки. $s3 мана відновлення кожні 5 секунд.",
        [1218075] = "Збільшує швидкість руху на $s1% і усі характеристики на $s3%.",
        [1218121] = "Збільшує критичний імовірність закляття на $s1%, ближнього бою і дальнього бою на $s3% і надає $s2 сила атаки.",
        [1218154] = "Підступний удар удари $s1 додатковий поблизу ціль.",
        [1218198] = "Павучий квартал посилено. Під час бою поблизу випадково з’являтимуться яйцеві мішки, що вибухають через кілька секунд.",
        [1218216] = "Завдає періодичної шкоди від природи. Ваші атаки можуть породжувати павучих прислужників, що кидаються на ворогів.",
        [1218271] = "Сили Скурджу міцнішають. Імовірність ухилення зменшено на ${$s1/$u}% і ймовірність бути влученим збільшено на ${$s2/$u}%.\r\n\r\nПереваги вашої Печатки Світанку не можуть перевищувати ранг $s3.",
        [1218275] = "Сили Скурджу міцнішають. Імовірність ухилення зменшено на ${$s1/$u}% і ймовірність бути влученим збільшено на ${$s2/$u}%. \r\n\r\nПереваги вашої Печатки Світанку не можуть перевищувати ранг ${$s3/$u}.",
        [1218276] = "Сили Скурджу міцнішають. Імовірність ухилення зменшено на ${$s1/$u}% і ймовірність бути влученим збільшено на ${$s2/$u}%.\r\n\r\nПереваги вашої Печатки Світанку не можуть перевищувати ранг ${$s3/$u}.",
        [1218283] = "Сам Король-ліч звернув увагу. Тут не лишилося надії. Імовірність ухилення зменшено на ${$s1/$u}% і ймовірність бути влученим збільшено на ${$s2/$u}%.\r\n\r\nПереваги вашої Печатки Світанку не можуть перевищувати ранг ${$s3/$u}.",
        [1218285] = "Не може отримати користь від ефекту «На взводі».",
        [1218345] = "Ціль отримує $s1% збільшено шкода від заклинателю's наступний Крижаний спис.",
        [1218358] = "Збільшує сила атаки ближнього бою на $s1 і зменшує броня на $s2. Ціль буде не тікати і буде ігнорувати Страх і Жах ефекти.",
        [1218366] = "Вас огортає крижана магічна темрява...",
        [1218479] = "Шкода і критичний шкода завдано до Невмерлі збільшено на $s1%.",
        [1218485] = "Шкоду цілям у Силітусі, Ан’Кіражі, Східних Зачумлених землях і Наксрамасі збільшено на $s1%.\r\nКритичну шкоду цілям у цих зонах також збільшено на $s2%.",
        [1218574] = "Імовірність критичного удару збільшено на $s1%.",
        [1218587] = "Шкода і критичний шкода завдано до Невмерлі збільшено на $s1%.",
        [1218695] = "Швидкість атак і вимовляння заклять збільшено на $s1%.",
