        [1219020] = "Темрява починає огортати вас, невідворотно завдаючи $w1 шкоди від тіні.",
        [1219058] = "Військовий квартал посилено. Під час бою випадково надходитимуть накази. Виконуйте їх або пожинайте наслідки!",
        [1219060] = "Робіть, що наказано!",
